14 | contract BasketFacet is ReentryProtection, CallProtection, IBasketFacet {
15 |     using SafeMath for uint256;
16 |     using SafeERC20 for IERC20;
17 | 
18 |     uint256 public constant MIN_AMOUNT = 10**6;
19 |     uint256 public constant MAX_ENTRY_FEE = 10**17; // 10%
20 |     uint256 public constant MAX_EXIT_FEE = 10**17; // 10%
21 |     uint256 public constant MAX_ANNUAL_FEE = 10**17; // 10%
22 |     uint256 public constant HUNDRED_PERCENT = 10**18;
23 | 
24 |     // Assuming a block gas limit of 12M this allows for a gas consumption per token of roughly 333k allowing 2M of overhead for addtional operations
25 |     uint256 public constant MAX_TOKENS = 30;
26 | 
27 |     function addToken(address _token) external override protectedCall {
28 |         LibBasketStorage.BasketStorage storage bs =
29 |             LibBasketStorage.basketStorage();
30 |         require(!bs.inPool[_token], "TOKEN_ALREADY_IN_POOL");
31 |         require(bs.tokens.length < MAX_TOKENS, "TOKEN_LIMIT_REACHED");
32 |         // Enforce minimum to avoid rounding errors; (Minimum value is the same as in Balancer)
33 |         require(balance(_token) >= MIN_AMOUNT, "BALANCE_TOO_SMALL");
34 | 
35 |         bs.inPool[_token] = true;
36 |         bs.tokens.push(IERC20(_token));
37 | 
38 |         emit TokenAdded(_token);
39 |     }
40 | 
41 |     function removeToken(address _token) external override protectedCall {
42 |         LibBasketStorage.BasketStorage storage bs =
43 |             LibBasketStorage.basketStorage();
44 | 
45 |         require(bs.inPool[_token], "TOKEN_NOT_IN_POOL");
46 | 
47 |         bs.inPool[_token] = false;
48 | 
49 |         // remove token from array
50 |         for (uint256 i; i < bs.tokens.length; i++) {
51 |             if (address(bs.tokens[i]) == _token) {
52 |                 bs.tokens[i] = bs.tokens[bs.tokens.length - 1];
53 |                 bs.tokens.pop();
54 |                 emit TokenRemoved(_token);
55 |                 break;
56 |             }
57 |         }
58 |     }
59 | 
60 |     function setEntryFee(uint256 _fee) external override protectedCall {
61 |         require(_fee <= MAX_ENTRY_FEE, "FEE_TOO_BIG");
62 |         LibBasketStorage.basketStorage().entryFee = _fee;
63 |         emit EntryFeeSet(_fee);
64 |     }
